#requires -Version 7.0
[CmdletBinding()]param([string]$Version='0.3.0-zh-test.1',[string]$OutputDirectory,[switch]$SkipPublish,[string]$ExistingApplication,[ValidatePattern('^r[0-9]+$')][string]$Revision='r12')
. (Join-Path $PSScriptRoot 'DevelopmentEnvironment.ps1')
if([string]::IsNullOrWhiteSpace($OutputDirectory)){$OutputDirectory=Join-Path $taskProjectRoot ('output/中文联调候选包_'+$Version+'_'+[DateTime]::UtcNow.ToString('yyyyMMddHHmmss'))}
$OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory);if(Test-Path -LiteralPath $OutputDirectory){throw '请指定新的输出目录，打包不覆盖旧包'};New-Item -ItemType Directory -Path $OutputDirectory|Out-Null
if(!$SkipPublish){
 Invoke-TaskPnpm run build
 Invoke-TaskDotnet restore (Join-Path $taskProjectRoot 'LevelManager.slnx') -r win-x64 '-p:SelfContained=true' --locked-mode --verbosity minimal
 foreach($item in @(@('src/LevelManager.Host/LevelManager.Host.csproj','server'),@('src/LevelManager.Desktop/LevelManager.Desktop.csproj','client'),@('tools/LevelManager.Maintenance/LevelManager.Maintenance.csproj','maintenance'))){Invoke-TaskDotnet publish (Join-Path $taskProjectRoot $item[0]) -c Release -r win-x64 --self-contained true --no-restore '-p:DebugType=None' '-p:DebugSymbols=false' -o (Join-Path $OutputDirectory ('app/'+$item[1])) '-m:1'}
}else{if(!$ExistingApplication -or ![IO.Path]::IsPathFullyQualified($ExistingApplication)){throw '跳过发布时须明确指定已验证的绝对app目录'};foreach($relative in @('server/LevelManager.Host.exe','client/LevelManager.Desktop.exe','maintenance/LevelManager.Maintenance.exe')){if(!(Test-Path -LiteralPath (Join-Path $ExistingApplication $relative))){throw '已有程序目录不完整'}};Copy-Item -LiteralPath $ExistingApplication -Destination (Join-Path $OutputDirectory 'app') -Recurse}
New-Item -ItemType Directory -Path (Join-Path $OutputDirectory 'docs') | Out-Null
foreach($taskDoc in Get-ChildItem -LiteralPath (Join-Path $taskProjectRoot 'deployment/docs') -File){if($taskDoc.Name -match '_r[0-9]+\.(html|csv)$' -and $taskDoc.Name -notmatch ('_'+$Revision+'\.(html|csv)$')){continue};Copy-Item -LiteralPath $taskDoc.FullName -Destination (Join-Path $OutputDirectory 'docs')}
foreach($name in @('Install.ps1','安装.cmd')){Copy-Item -LiteralPath (Join-Path $taskProjectRoot ('deployment/'+$name)) -Destination $OutputDirectory}
Copy-Item -LiteralPath (Join-Path $taskProjectRoot 'deployment/client.json') -Destination (Join-Path $OutputDirectory 'app/client/client.json')
$prerequisites=Join-Path $OutputDirectory 'prerequisites';New-Item -ItemType Directory -Path $prerequisites|Out-Null;$runtime=Join-Path $taskProjectRoot '.build-tools/offline-runtimes/MicrosoftEdgeWebView2RuntimeInstallerX64.exe';$signature=Get-AuthenticodeSignature -LiteralPath $runtime;if($signature.Status -ne 'Valid' -or $signature.SignerCertificate.Subject -notmatch 'O=Microsoft Corporation' -or (Get-Item -LiteralPath $runtime).Length -lt 100000000){throw '缺少签名有效的完整微软离线运行环境，禁止用在线引导器代替'};Copy-Item -LiteralPath $runtime -Destination $prerequisites
$notices=Join-Path $OutputDirectory 'docs/第三方许可';New-Item -ItemType Directory -Path $notices|Out-Null
foreach($name in @('vue','vue-router','pinia','echarts','zrender')){foreach($file in @('LICENSE','LICENSE.txt','NOTICE')){$source=Join-Path $taskProjectRoot ('web/node_modules/'+$name+'/'+$file);if(Test-Path -LiteralPath $source){Copy-Item -LiteralPath $source -Destination (Join-Path $notices ($name+'-'+$file+'.txt'))}}}
$webViewLicense=Join-Path $taskProjectRoot '.build-tools/nuget/microsoft.web.webview2/1.0.4314.35/LICENSE.txt';if(Test-Path -LiteralPath $webViewLicense){Copy-Item -LiteralPath $webViewLicense -Destination (Join-Path $notices 'WebView2-SDK-LICENSE.txt')}
& (Join-Path $PSScriptRoot 'copy-package-notices.ps1') -ApplicationRoot (Join-Path $OutputDirectory 'app') -Destination $notices
$forbidden=Get-ChildItem -LiteralPath $OutputDirectory -File -Recurse|Where-Object{$_.Extension -in '.pem','.pfx','.key','.db' -or $_.Name -match 'LevelManager.Tools|VendorAuthorization|license\.json|installation\.dat|clock\.dat|password|mock-gateway|node.exe|python.exe'};if($forbidden){throw '交付目录含供方工具、密钥或已有客户数据，停止打包'}
$files=@(Get-ChildItem -LiteralPath $OutputDirectory -File -Recurse|Sort-Object FullName|ForEach-Object{[ordered]@{path=[IO.Path]::GetRelativePath($OutputDirectory,$_.FullName).Replace('\','/');bytes=$_.Length;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash}})
[ordered]@{productId='Naide.LevelManager.2026';version=$Version;revision=$Revision;schemaVersion=16;plannedSoakSeconds=21600;stage='中文联调候选版，待现场与安装验收';builtAtUtc=[DateTime]::UtcNow.ToString('o');target='win-x64';maximumTanks=128;historySeconds=60;retentionMonths=12;language='zh-CN';averageResources=$true;customerExpirationPreset=$false;containsSupplierSigningTools=$false;files=$files}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $OutputDirectory 'package-manifest.json') -Encoding UTF8
Write-Output ('已生成待验证目录：'+$OutputDirectory)
Write-Output '本脚本未注册服务或安装系统组件；验证完成后再生成发放ZIP。'
